var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // 'seconds' is a valid unit in ms 2.1.3; the patch dropped its switch case
    assert.strictEqual(ms('2 seconds'), 2000);
    assert.strictEqual(ms('100 seconds'), 100000);
    // sanity: singular and abbreviated forms still work
    assert.strictEqual(ms('1 second'), 1000);
    assert.strictEqual(ms('2s'), 2000);
  });
});
"}, "note": "Removing case 'seconds' makes ms('2 seconds') fall through to default and return undefined instead of 2000, while the added case "": is unreachable because an unmatched unit group yields undefined (handled by `|| 'ms'`), never an empty string."}
```

